-- Schema ms1 của MISDB (cấu trúc lấy từ openmetadata-python-client/misdb/MISDB_metadata_v4.csv): 1395 bảng, chỉ có cấu trúc, dữ liệu mẫu chỉ có ở TBCM_GENERAL.
-- Chạy một lần sau khi Oracle tạo xong database (thư mục /opt/oracle/scripts/setup), bằng "sqlplus / as sysdba".
WHENEVER SQLERROR EXIT SQL.SQLCODE
ALTER SESSION SET CONTAINER = MISDB;

CREATE USER ms1 NO AUTHENTICATION DEFAULT TABLESPACE users QUOTA UNLIMITED ON users;

-- Tài khoản chỉ đọc cho OpenMetadata (ingest metadata và chạy pipeline kiểm thử)
CREATE USER dq_reader IDENTIFIED BY "dq_reader_pw";
GRANT CREATE SESSION TO dq_reader;
GRANT SELECT_CATALOG_ROLE TO dq_reader;
GRANT SELECT ANY DICTIONARY TO dq_reader;

