-- Dữ liệu mẫu: 1000 dòng mỗi bảng, CUSTSEQ khớp nhau giữa hai bảng.
-- Số CCCD sai định dạng 12 chữ số: 30 dòng mỗi bảng (10 có chữ, 10 thiếu số, 10 NULL)
INSERT INTO ms1.TBCM_GENERAL (BRCD, CUSTSEQ, STSCD, IDTPCDNATL, IDNONATL, NM)
SELECT LPAD(MOD(LEVEL, 50) + 1, 4, '0'), LPAD(LEVEL, 9, '0'), '01', '01',
       CASE MOD(LEVEL, 100) WHEN 7 THEN '00120100' || LPAD(LEVEL, 3, '0') || 'X'
       WHEN 8 THEN '0012010' || LPAD(LEVEL, 3, '0')
       WHEN 9 THEN NULL
       ELSE '001201' || LPAD(LEVEL, 6, '0') END,
       'Khach hang ' || LEVEL
FROM dual CONNECT BY LEVEL <= 1000;

INSERT INTO ms1.TBCM_CUSTID (BRCD, CUSTSEQ, IDTPCD, SEQ, STSCD, IDNO)
SELECT LPAD(MOD(LEVEL, 50) + 1, 4, '0'), LPAD(LEVEL, 9, '0'), '01', 1, '01',
       CASE MOD(LEVEL, 100) WHEN 7 THEN '00120100' || LPAD(LEVEL, 3, '0') || 'X'
       WHEN 8 THEN '0012010' || LPAD(LEVEL, 3, '0')
       WHEN 9 THEN NULL
       ELSE '001201' || LPAD(LEVEL, 6, '0') END
FROM dual CONNECT BY LEVEL <= 1000;
COMMIT;

-- Cấp quyền đọc cho tài khoản chỉ đọc
BEGIN
  FOR t IN (SELECT table_name FROM dba_tables WHERE owner = 'MS1') LOOP
    EXECUTE IMMEDIATE 'GRANT SELECT ON ms1."' || t.table_name || '" TO dq_reader';
  END LOOP;
END;
/
